function validate([n, ranges]) {
  if (!Number.isInteger(n) || n < 1 || n > 10000) return 'n is a whole number from 1 to 10000.';
  if (ranges.length !== n + 1) return 'ranges needs exactly n + 1 values.';
  if (ranges.some(r => !Number.isInteger(r) || r < 0 || r > 100)) return 'Each range is a whole number from 0 to 100.';
  return null;
}

