function minTaps(n, ranges) {
  const reach = new Array(n + 1).fill(0);
  for (let i = 0; i <= n; i++) {
    const left = Math.max(0, i - ranges[i]);
    const right = Math.min(n, i + ranges[i]);
    reach[left] = Math.max(reach[left], right);
  }

  let taps = 0;
  let covered = 0;
  let farthest = 0;
  for (let x = 0; x < n; x++) {
    farthest = Math.max(farthest, reach[x]);
    if (x === covered) {
      if (farthest <= x) {
        return -1;
      }
      taps++;
      covered = farthest;
    }
  }
  return taps;
}

