function minTaps(n, ranges) {
  // best[x] = fewest taps whose segments together cover [0, x].
  const best = new Array(n + 1).fill(Infinity);
  best[0] = 0;
  for (let x = 1; x <= n; x++) {
    for (let i = 0; i <= n; i++) {
      const lo = Math.max(0, i - ranges[i]), hi = i + ranges[i];
      if (lo < x && x <= hi && best[lo] + 1 < best[x]) best[x] = best[lo] + 1;
    }
  }
  return best[n] === Infinity ? -1 : best[n];
}

