function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 499) : 1 + Math.floor(rand() * 12);
  const cap = size === 'large' ? 100 : 1 + Math.floor(rand() * 5);
  // Each input picks how often a tap has any range, so some gardens have gaps and some do not.
  const density = size === 'large' ? 0.03 + rand() * 0.2 : 0.2 + rand() * 0.8;
  const ranges = Array.from({ length: n + 1 }, () => rand() < density ? Math.floor(rand() * (cap + 1)) : 0);
  return [n, ranges];
}
